using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ApiFetchTool
{
    [McpServerTool("fetch_post"), Description("Fetches a post by ID from the external API.")]
    public static async Task<string> FetchPostAsync(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric post ID to retrieve.")] int id,
        CancellationToken cancellationToken)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"posts/{id}", cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a summarization prompt for the given text.")]
    public static GetPromptResult Summarize(
        [Description("The text to summarize.")] string text)
    {
        return new GetPromptResult
        {
            Description = "Summarize the provided text.",
            Messages =
            [
                new PromptMessage
                {
                    Role = Role.User,
                    Content = new Content
                    {
                        Type = "text",
                        Text = $"Please provide a concise summary of the following text:\n\n{text}"
                    }
                }
            ]
        };
    }
}

