import subprocess, tempfile, os

code = '''
using System;
using System.Reflection;
using System.Linq;

var asm = Assembly.LoadFrom(Environment.GetEnvironmentVariable("MCP_DLL"));
var names = new[] { "PromptMessage", "Content", "McpServerToolAttribute", "McpServerPromptAttribute", "GetPromptResult", "Role", "TextContent" };
foreach (var t in asm.GetTypes().Where(t => names.Contains(t.Name))) {
    Console.WriteLine($"--- {t.FullName} ---");
    if (t.BaseType != null && t.BaseType != typeof(object))
        Console.WriteLine($"  Base: {t.BaseType.FullName}");
    foreach (var p in t.GetProperties(BindingFlags.Public | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly))
        Console.WriteLine($"  P: {p.PropertyType.Name} {p.Name}");
    foreach (var c in t.GetConstructors())
        Console.WriteLine($"  C: ({string.Join(", ", c.GetParameters().Select(p => $"{p.ParameterType.Name} {p.Name}"))})");
    if (t.IsEnum) foreach (var v in Enum.GetNames(t)) Console.WriteLine($"  E: {v}");
}
'''

with tempfile.TemporaryDirectory() as d:
    proj = os.path.join(d, "Inspect.csproj")
    with open(proj, 'w') as f:
        f.write('''<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net9.0</TargetFramework></PropertyGroup>
  <ItemGroup><PackageReference Include="ModelContextProtocol" Version="1.4.0" /></ItemGroup>
</Project>''')
    prog = os.path.join(d, "Program.cs")
    with open(prog, 'w') as f:
        f.write(code)

    dll = os.path.expanduser("~/.nuget/packages/modelcontextprotocol/1.4.0/lib/net9.0/ModelContextProtocol.dll")
    env = os.environ.copy()
    env["MCP_DLL"] = dll
    r = subprocess.run(["dotnet", "run", "--project", d], capture_output=True, text=True, env=env, timeout=60)
    print(r.stdout)
    if r.stderr:
        print("STDERR:", r.stderr[-500:])
EOF

